/*! Local jQuery-compatible AJAX shim (network-restricted environment) */
(function(window){"use strict";function param(v){if(typeof v==="string"){return v;}if(!v){return "";}var out=[];for(var k in v){if(Object.prototype.hasOwnProperty.call(v,k)){out.push(encodeURIComponent(k)+"="+encodeURIComponent(v[k]));}}return out.join("&");}function ajax(opts){opts=opts||{};var method=(opts.type||opts.method||"GET").toUpperCase();var async=opts.async!==false;var data=param(opts.data);var url=opts.url||"";var xhr=new XMLHttpRequest();if(method==="GET"&&data){url+=(url.indexOf("?")===-1?"?":"&")+data;data="";}xhr.open(method,url,async);if(method!=="GET"){xhr.setRequestHeader("Content-Type",opts.contentType||"application/x-www-form-urlencoded; charset=UTF-8");}xhr.onreadystatechange=function(){if(xhr.readyState!==4){return;}var ok=(xhr.status>=200&&xhr.status<300)||xhr.status===304;if(ok&&typeof opts.success==="function"){opts.success(xhr.responseText,"success",xhr);}if(!ok&&typeof opts.error==="function"){opts.error(xhr,"error",xhr.statusText||"error");}if(typeof opts.complete==="function"){opts.complete(xhr,ok?"success":"error");}};xhr.send(data||null);return xhr;}function get(url,data,success){if(typeof data==="function"){success=data;data="";}return ajax({url:url,type:"GET",data:data,success:success});}function post(url,data,success){if(typeof data==="function"){success=data;data="";}return ajax({url:url,type:"POST",data:data,success:success});}var jq=function(){};jq.ajax=ajax;jq.param=param;jq.get=get;jq.post=post;window.jQuery=window.$=jq;})(window);
